ops.content:
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Get-UtcIso { ([DateTime]::UtcNow.ToString('o')) }

function Resolve-Python {
  # Preference: py -3.11, then py, then python
  $candidates = @(
    @{ exe='py'; args=@('-3.11') },
    @{ exe='py'; args=@() },
    @{ exe='python'; args=@() }
  )
  foreach ($c in $candidates) {
    try {
      $null = Get-Command $c.exe -ErrorAction Stop
      $out = & $c.exe @($c.args + @('-c', 'import sys; print(sys.version)')) 2>$null
      if ($LASTEXITCODE -eq 0 -and $out) { return $c }
    } catch { }
  }
  return $null
}

function Run-Capture {
  param(
    [Parameter(Mandatory=$true)][string]$Exe,
    [Parameter(Mandatory=$false)][string[]]$Args = @()
  )
  $out = & $Exe @Args 2>&1
  return [ordered]@{ rc = $LASTEXITCODE; out = ($out | Out-String) }
}

function Run-PyCapture {
  param(
    [Parameter(Mandatory=$true)][string]$PyExe,
    [Parameter(Mandatory=$true)][string[]]$PyBase,
    [Parameter(Mandatory=$true)][string[]]$Args
  )
  $out = & $PyExe @($PyBase + $Args) 2>&1
  return [ordered]@{ rc = $LASTEXITCODE; out = ($out | Out-String) }
}

function Tail-Text {
  param([string]$Text, [int]$MaxChars = 1800)
  if (-not $Text) { return $null }
  if ($Text.Length -le $MaxChars) { return $Text }
  return $Text.Substring($Text.Length - $MaxChars)
}

$ts = Get-UtcIso
$result = [ordered]@{
  schema = 'bootstrap_tools_v1'
  ts_utc = $ts
  ok = $false
  exit_code = 2
  python = $null
  pip = $null
  tools = [ordered]@{ ruff = $null; pyinstaller = $null }
  actions = @()
  pip_tail = $null
  error = $null
}

try {
  $py = Resolve-Python
  if (-not $py) {
    $result.error = 'Python not found (expected: py or python in PATH)'
    $result.exit_code = 2
    $result | ConvertTo-Json -Depth 10 -Compress
    exit 2
  }

  $pyExe = $py.exe
  $pyBase = [string[]]$py.args

  $pyPath = & $pyExe @($pyBase + @('-c', 'import sys; print(sys.executable)'))
  if ($LASTEXITCODE -ne 0) { throw 'Failed to query python executable' }
  $result.python = ($pyPath | Select-Object -First 1)

  $pipVer = & $pyExe @($pyBase + @('-m','pip','--version'))
  if ($LASTEXITCODE -ne 0) { throw 'pip not available' }
  $result.pip = ($pipVer | Select-Object -First 1)

  # 1) Detect ruff without installing
  $ruffDetected = $false
  try {
    $c = Get-Command ruff -ErrorAction Stop
    $rv = Run-Capture -Exe $c.Source -Args @('--version')
    if ($rv.rc -eq 0) {
      $result.tools.ruff = ($rv.out.Trim())
      $ruffDetected = $true
      $result.actions += 'ruff_detected: cmd'
    }
  } catch { }

  if (-not $ruffDetected) {
    $rv2 = Run-PyCapture -PyExe $pyExe -PyBase $pyBase -Args @('-m','ruff','--version')
    if ($rv2.rc -eq 0) {
      $result.tools.ruff = ($rv2.out.Trim())
      $ruffDetected = $true
      $result.actions += 'ruff_detected: python_module'
    }
  }

  if (-not $ruffDetected) {
    $result.actions += 'pip_install_upgrade: ruff'
    $install = Run-PyCapture -PyExe $pyExe -PyBase $pyBase -Args @('-m','pip','install','-U','ruff','--disable-pip-version-check','--no-input')
    if ($install.rc -ne 0) {
      # fallback: --user (permission-safe)
      $result.actions += 'pip_install_upgrade: ruff (--user fallback)'
      $install2 = Run-PyCapture -PyExe $pyExe -PyBase $pyBase -Args @('-m','pip','install','-U','ruff','--user','--disable-pip-version-check','--no-input')
      $result.pip_tail = Tail-Text -Text ($install.out + "\n---\n" + $install2.out)
      if ($install2.rc -ne 0) { throw 'pip install -U ruff failed' }
    }
    $rv3 = Run-PyCapture -PyExe $pyExe -PyBase $pyBase -Args @('-m','ruff','--version')
    if ($rv3.rc -ne 0) {
      $result.pip_tail = Tail-Text -Text ($result.pip_tail + "\n" + $rv3.out)
      throw 'ruff still not available after install'
    }
    $result.tools.ruff = ($rv3.out.Trim())
  }

  # 2) Detect pyinstaller without installing
  $piDetected = $false
  try {
    $c2 = Get-Command pyinstaller -ErrorAction Stop
    $pv = Run-Capture -Exe $c2.Source -Args @('--version')
    if ($pv.rc -eq 0) {
      $result.tools.pyinstaller = ($pv.out.Trim())
      $piDetected = $true
      $result.actions += 'pyinstaller_detected: cmd'
    }
  } catch { }

  if (-not $piDetected) {
    $pv2 = Run-PyCapture -PyExe $pyExe -PyBase $pyBase -Args @('-m','PyInstaller','--version')
    if ($pv2.rc -eq 0) {
      $result.tools.pyinstaller = ($pv2.out.Trim())
      $piDetected = $true
      $result.actions += 'pyinstaller_detected: python_module'
    }
  }

  if (-not $piDetected) {
    $result.actions += 'pip_install_upgrade: pyinstaller'
    $inst = Run-PyCapture -PyExe $pyExe -PyBase $pyBase -Args @('-m','pip','install','-U','pyinstaller','--disable-pip-version-check','--no-input')
    if ($inst.rc -ne 0) {
      $result.actions += 'pip_install_upgrade: pyinstaller (--user fallback)'
      $inst2 = Run-PyCapture -PyExe $pyExe -PyBase $pyBase -Args @('-m','pip','install','-U','pyinstaller','--user','--disable-pip-version-check','--no-input')
      $result.pip_tail = Tail-Text -Text (($result.pip_tail ?? '') + "\n" + $inst.out + "\n---\n" + $inst2.out)
      if ($inst2.rc -ne 0) { throw 'pip install -U pyinstaller failed' }
    }
    $pv3 = Run-PyCapture -PyExe $pyExe -PyBase $pyBase -Args @('-m','PyInstaller','--version')
    if ($pv3.rc -ne 0) {
      $result.pip_tail = Tail-Text -Text (($result.pip_tail ?? '') + "\n" + $pv3.out)
      throw 'PyInstaller still not available after install'
    }
    $result.tools.pyinstaller = ($pv3.out.Trim())
  }

  $result.ok = $true
  $result.exit_code = 0
  $result | ConvertTo-Json -Depth 12 -Compress
  exit 0
}
catch {
  $result.ok = $false
  $result.exit_code = 2
  $result.error = ($_.Exception.Message)
  $result | ConvertTo-Json -Depth 12 -Compress
  exit 2
}
